def inter_byte_timeout(baudrate):
    # EN 13757-2 maximum response time is 330 bit times + 50 ms.
    # Shorter timers (notably 300 baud) expire before a short frame has
    # left the UART, so the far end receives nothing.
    try:
        baudrate = float(baudrate)
    except (TypeError, ValueError):
        return None

    if baudrate not in (300.0, 600.0, 1200.0, 2400.0, 4800.0, 9600.0, 19200.0, 38400.0):
        return None

    return 330.0 / baudrate + 0.05

