def _as_int(value):
    if isinstance(value, (list, tuple)):
        if len(value) != 1:
            raise TypeError("not a single address")
        value = value[0]

    if isinstance(value, str):
        text = value.strip()
        try:
            return int(text, 0)
        except ValueError:
            try:
                return int(text, 16)
            except ValueError:
                if len(text) == 1:
                    return ord(text)
                raise

    if isinstance(value, (bytes, bytearray, memoryview)):
        raw = bytes(value)
        if len(raw) == 1:
            return raw[0]
        text = raw.strip()
        try:
            return int(text, 0)
        except ValueError:
            return int(text, 16)

    if type(value) is bool:
        raise TypeError("bool is not an address")

    if isinstance(value, int):
        return value

    number = int(value)
    if isinstance(value, float) and not value.is_integer():
        raise TypeError("fractional address")
    return number


